package com.rafi.daybook;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.provider.Settings;import android.webkit.*;import android.view.View;import android.widget.Toast;import java.io.*;
public class MainActivity extends Activity {
 private WebView web;private ValueCallback<Uri[]> upload;private String backup;
 @Override public void onCreate(Bundle state){super.onCreate(state);web=new WebView(this);setContentView(web);web.setPadding(0,0,0,0);web.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(true);web.addJavascriptInterface(new Bridge(),"DaybookAndroid");web.setWebViewClient(new WebViewClient(){
  @Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest req){return !"appassets.androidplatform.net".equals(req.getUrl().getHost());}
  @Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest req){if(!"appassets.androidplatform.net".equals(req.getUrl().getHost()))return null;String p=req.getUrl().getPath();if(p.contains(".."))return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));if(p.equals("/"))p="/index.html";String mime=p.endsWith(".js")?"text/javascript":p.endsWith(".css")?"text/css":p.endsWith(".svg")?"image/svg+xml":p.endsWith(".json")?"application/json":"text/html";try{return new WebResourceResponse(mime,"UTF-8",getAssets().open("www"+p));}catch(IOException e){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}}
 });web.setWebChromeClient(new WebChromeClient(){@Override public boolean onJsConfirm(WebView v,String url,String message,JsResult result){new AlertDialog.Builder(MainActivity.this).setMessage(message).setPositiveButton("OK",(d,w)->result.confirm()).setNegativeButton("Cancel",(d,w)->result.cancel()).setOnCancelListener(d->result.cancel()).show();return true;}@Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> cb,FileChooserParams params){if(upload!=null)upload.onReceiveValue(null);upload=cb;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,10);return true;}});web.loadUrl("https://appassets.androidplatform.net/index.html");Reminders.restore(this);}
 @Override protected void onResume(){super.onResume();Reminders.restore(this);}
 private void exactPermission(){AlarmManager am=getSystemService(AlarmManager.class);if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms()){Toast.makeText(this,"Enable Alarms & reminders for midnight reminders.",Toast.LENGTH_LONG).show();startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));}else Toast.makeText(this,"Notifications enabled.",Toast.LENGTH_SHORT).show();}
 class Bridge {
  @JavascriptInterface public void schedule(String json){Reminders.replace(MainActivity.this,json);}
  @JavascriptInterface public void requestNotifications(){runOnUiThread(()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},11);else exactPermission();});}
  @JavascriptInterface public void exportBackup(String json){runOnUiThread(()->{backup=json;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"daybook-backup.json");startActivityForResult(intent,12);});}
 }
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] results){super.onRequestPermissionsResult(r,p,results);if(r==11&&results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)exactPermission();else Toast.makeText(this,"Notifications need permission in Settings.",Toast.LENGTH_LONG).show();}
 @Override protected void onActivityResult(int req,int result,Intent intent){super.onActivityResult(req,result,intent);if(req==10&&upload!=null){upload.onReceiveValue(result==RESULT_OK&&intent!=null?new Uri[]{intent.getData()}:null);upload=null;}if(req==12&&result==RESULT_OK&&intent!=null&&backup!=null){try(OutputStream out=getContentResolver().openOutputStream(intent.getData())){out.write(backup.getBytes(java.nio.charset.StandardCharsets.UTF_8));Toast.makeText(this,"Backup exported.",Toast.LENGTH_SHORT).show();}catch(IOException e){Toast.makeText(this,"Could not export backup.",Toast.LENGTH_LONG).show();}backup=null;}}
 @Override public void onBackPressed(){web.evaluateJavascript("if(document.querySelector('dialog[open]')) document.querySelector('dialog[open]').close(); else location.hash='tasks';",null);}
}

